import{_ as a,m as t,n as i,q as o}from"./chunks/framework.DMDh-7Lg.js";const c=JSON.parse('{"title":"Example: Full Demo","description":"","frontmatter":{},"headers":[],"relativePath":"examples/full-demo.md","filePath":"examples/full-demo.md"}'),s={name:"examples/full-demo.md"};function r(l,e,n,h,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="example-full-demo" tabindex="-1">Example: Full Demo <a class="header-anchor" href="#example-full-demo" aria-label="Permalink to &quot;Example: Full Demo&quot;">​</a></h1><p>The repository’s <code>examples/full_demo.py</code> file is the broadest walkthrough of the framework. It pulls together most of the major features in one place.</p><p>Use it when you want to see how Klix behaves as a more complete application rather than a minimal sketch.</p><h2 id="what-this-example-demonstrates" tabindex="-1">What This Example Demonstrates <a class="header-anchor" href="#what-this-example-demonstrates" aria-label="Permalink to &quot;What This Example Demonstrates&quot;">​</a></h2><p>The full demo shows:</p><ul><li>typed session state with persistence enabled</li><li>startup and shutdown events</li><li>middleware that wraps command execution</li><li>layout regions for header and status</li><li>structured output widgets</li><li>interactive input components</li><li>background tasks</li><li>a state migration hook</li></ul><p>It is the closest thing in the repository to a framework tour by example.</p><h2 id="why-this-example-matters" tabindex="-1">Why This Example Matters <a class="header-anchor" href="#why-this-example-matters" aria-label="Permalink to &quot;Why This Example Matters&quot;">​</a></h2><p>A lot of Klix’s value is not in any single feature. It comes from how the pieces work together:</p><ul><li>the <code>App</code> creates the runtime</li><li>the <code>Session</code> carries state and UI</li><li>the router parses command input</li><li>middleware wraps handlers</li><li>events let you hook the lifecycle</li><li>widgets make the CLI feel intentional instead of raw</li></ul><p><code>examples/full_demo.py</code> is where all of that becomes visible at once.</p><h2 id="key-patterns-to-notice" tabindex="-1">Key Patterns To Notice <a class="header-anchor" href="#key-patterns-to-notice" aria-label="Permalink to &quot;Key Patterns To Notice&quot;">​</a></h2><h3 id="layout-first-startup" tabindex="-1">Layout-first startup <a class="header-anchor" href="#layout-first-startup" aria-label="Permalink to &quot;Layout-first startup&quot;">​</a></h3><p>The example clears the screen, sets a header and status line, redraws the layout, and then prints normal output. That is the right order when you want a polished startup experience.</p><p>See <a href="./../concepts/layout">Layout</a>.</p><h3 id="middleware-for-cross-cutting-behavior" tabindex="-1">Middleware for cross-cutting behavior <a class="header-anchor" href="#middleware-for-cross-cutting-behavior" aria-label="Permalink to &quot;Middleware for cross-cutting behavior&quot;">​</a></h3><p>The example updates status before and after command execution in middleware rather than repeating that code in every handler.</p><p>See <a href="./../guides/using-middleware">Using Middleware</a>.</p><h3 id="state-migration-for-persisted-apps" tabindex="-1">State migration for persisted apps <a class="header-anchor" href="#state-migration-for-persisted-apps" aria-label="Permalink to &quot;State migration for persisted apps&quot;">​</a></h3><p>Because the app enables persistence, it also includes a migration hook. That is an important production habit even in a lightweight framework.</p><p>See <a href="./../guides/persistence">Persistence</a>.</p><h3 id="background-work-through-the-session" tabindex="-1">Background work through the session <a class="header-anchor" href="#background-work-through-the-session" aria-label="Permalink to &quot;Background work through the session&quot;">​</a></h3><p>The demo uses session-managed tasks for work that should outlive a single handler call but still belong to the active session.</p><p>See <a href="./../concepts/session">Session</a>.</p><h2 id="practical-takeaways" tabindex="-1">Practical Takeaways <a class="header-anchor" href="#practical-takeaways" aria-label="Permalink to &quot;Practical Takeaways&quot;">​</a></h2><p>If you are building a real internal CLI, this example is a better starting point than the minimal example because it already includes:</p><ul><li>status management</li><li>persistence</li><li>richer UI patterns</li><li>more realistic command structure</li></ul><p>The tradeoff is that it is a lot to absorb at once, so read it after the concept pages.</p><h2 id="pitfalls-it-helps-you-avoid" tabindex="-1">Pitfalls It Helps You Avoid <a class="header-anchor" href="#pitfalls-it-helps-you-avoid" aria-label="Permalink to &quot;Pitfalls It Helps You Avoid&quot;">​</a></h2><ul><li>forgetting to redraw the layout after changing regions</li><li>putting cross-cutting behavior into command handlers</li><li>storing ad hoc global state outside the session</li><li>treating rich output as the only supported path instead of accounting for fallback renderers</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./../concepts/state">State</a></li><li><a href="./../concepts/middleware">Middleware</a></li><li><a href="./../components/widgets">Components: Widgets</a></li></ul>',32)])])}const m=a(s,[["render",r]]);export{c as __pageData,m as default};
